response:
**Gates before launch.** Any gate that fails halts the round, and I report back to you. Gate 1: `git status --porcelain` must come back empty for spe/predictions/r04.yaml, spe/plans/r04.md, spe/evals/graders/, and spe/evals/tasks/answers.json. That proves the run tests the prediction that was committed. Gate 2 is the grader selftest. grade.py must score the oracle (answers.json fed back as outputs) at 50 of 50 on both label.category and label.priority. It must also fail all 50 tickets for empty outputs and for wrong labels. Gate 3 is the control. I regrade round 3's saved outputs with today's grade.py, and the numbers must match the r03 measured rows in spe/prediction-log.md. Gate 4 is the dry run. I launch the script below with `{dryRun: true}`, which runs 3 cells (B/T001, B/T002, C2/T001) once each into spe/evals/runs/r04-dry. I check that every schema field comes back, the peek scan runs, and the judge returns a score. Then I read the dry run's real cost and pass it in as `trialUsd` and `judgeUsd`. 500 trials plus 500 judge calls might cost more than $40 minus the $1 reserve. In that case I halt and ask you, because the cap and the trial count are your decisions. When all four gates pass, I commit the script as `SPE r04 evaluate (harness)` and launch with `{trialUsd, judgeUsd}`.

Defaults I chose: I assumed these carry over from r03-workflow.js unchanged: round 3's runner spe/evals/harness/run_trial.py and its flags, grade.py's `--json` output, ticket files spe/evals/tasks/tickets/T001.json to T050.json, and Opus for the harness agents.

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE eval: configs B and C2, 50 tickets, 5 trials per cell, code grader first, Opus tone judge, 40 USD cap',
  phases: ['Preflight', 'Trials', 'Extra trials', 'Score', 'Failure analysis', 'Completeness critic']
}

// The round lives here only. Prompts and paths derive from it.
const ROUND = 4
const RR = `r${String(ROUND).padStart(2, '0')}`

const A = (typeof args === 'object' && args !== null) ? args : {}
const DRY = A.dryRun === true

const CONFIGS = ['B', 'C2']
const TICKETS = Array.from({ length: 50 }, (_, i) => `T${String(i + 1).padStart(3, '0')}`)
const BASE_TRIALS = DRY ? 1 : 5
const DRY_CELLS = [
  { config: 'B', ticket: 'T001' },
  { config: 'B', ticket: 'T002' },
  { config: 'C2', ticket: 'T001' }
]
const CELLS = DRY
  ? (A.cells ?? DRY_CELLS)
  : CONFIGS.flatMap(config => TICKETS.map(ticket => ({ config, ticket })))

// Split cells get extra trials up to these caps. Predictions are scored on base trials only.
const EXTRA_PER_SPLIT = DRY ? 0 : (A.extraPerSplit ?? 3)
const EXTRA_MAX = DRY ? 0 : (A.extraMax ?? 60)

// Spend. Per-call costs are estimates calibrated by the dry run and passed in args.
const CAP_USD = 40
const TRIAL_USD = A.trialUsd ?? 0.05
const JUDGE_USD = A.judgeUsd ?? 0.025
const ANALYSIS_USD = A.analysisUsd ?? 0.5
const RESERVE_USD = 2 * ANALYSIS_USD

const GRADER_ERROR_HALT = 3

const RUN_DIR = DRY ? `spe/evals/runs/${RR}-dry` : `spe/evals/runs/${RR}`
const RUNNER = 'spe/evals/harness/run_trial.py'
const GRADER = 'spe/evals/graders/grade.py'
const ANSWERS = 'spe/evals/tasks/answers.json'
const RUBRIC = 'spe/evals/graders/judge.md'
const TICKET_DIR = 'spe/evals/tasks/tickets'
const PREDICTIONS = `spe/predictions/${RR}.yaml`
const PLAN = `spe/plans/${RR}.md`
const PROTECTED = [GRADER, RUBRIC, ANSWERS, PREDICTIONS, PLAN]
const PEEK_PATTERN = 'answers\\.json|evals/graders|spe/predictions|spe/plans|prediction-log|failures\\.md'

// ---------- state ----------
let spent = 0
let halted = null
let graderErrors = 0
let done = 0
const skips = []

function halt(reason) {
  if (!halted) {
    halted = reason
    log(`HALT: ${reason}. No new trials or judge calls will start.`)
  }
}

// Reserve estimated spend before a paid call. Skip and log if it would cross the cap.
function reserve(usd, what, opts = {}) {
  const analysis = opts.analysis === true
  if (halted && !analysis) {
    skips.push({ what, reason: `halted: ${halted}` })
    return false
  }
  const limit = analysis ? CAP_USD : CAP_USD - RESERVE_USD
  if (spent + usd > limit) {
    skips.push({ what, reason: 'cap', est_spent_usd: +spent.toFixed(2) })
    log(`SKIP ${what}: estimated spend $${(spent + usd).toFixed(2)} would cross $${limit.toFixed(2)}`)
    return false
  }
  spent += usd
  return true
}

const rate = (xs, f) => (xs.length ? +(xs.filter(f).length / xs.length).toFixed(3) : null)

function groupByCell(recs) {
  const m = new Map()
  for (const r of recs) {
    const k = `${r.config}/${r.ticket}`
    if (!m.has(k)) m.set(k, [])
    m.get(k).push(r)
  }
  return m
}

function countBy(recs, f) {
  const out = {}
  for (const r of recs) out[f(r)] = (out[f(r)] ?? 0) + 1
  return out
}

// ---------- schemas ----------
const PREFLIGHT_SCHEMA = {
  type: 'object',
  required: ['clean', 'problems'],
  properties: {
    clean: { type: 'boolean' },
    problems: { type: 'array', items: { type: 'string' } }
  }
}

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ran', 'run_error', 'output_path', 'category', 'priority', 'reply_text',
    'category_ok', 'priority_ok', 'grader_error', 'peek_hits'],
  properties: {
    ran: { type: 'boolean' },
    run_error: { type: 'string' },
    output_path: { type: 'string' },
    category: { type: 'string' },
    priority: { type: 'string' },
    reply_text: { type: 'string' },
    category_ok: { type: 'boolean' },
    priority_ok: { type: 'boolean' },
    grader_error: { type: 'string' },
    peek_hits: { type: 'array', items: { type: 'string' } }
  }
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['tone_pass', 'score', 'reason'],
  properties: {
    tone_pass: { type: 'boolean' },
    score: { type: 'integer', minimum: 1, maximum: 5 },
    reason: { type: 'string' }
  }
}

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types', 'grader_suspects', 'notes'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'matches_existing', 'what', 'how_to_spot', 'seen_in', 'count', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['model', 'config', 'task', 'grader', 'judge', 'harness'] },
          matches_existing: { type: 'string' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          fix: { type: 'string' }
        }
      }
    },
    grader_suspects: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'why'],
        properties: { id: { type: 'string' }, why: { type: 'string' } }
      }
    },
    notes: { type: 'string' }
  }
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'integrity_clean', 'output_files_found', 'gaps', 'halt_reasons'],
  properties: {
    complete: { type: 'boolean' },
    integrity_clean: { type: 'boolean' },
    output_files_found: { type: 'integer' },
    gaps: { type: 'array', items: { type: 'string' } },
    halt_reasons: { type: 'array', items: { type: 'string' } }
  }
}

// ---------- prompts ----------
function preflightPrompt() {
  return [
    `You check that SPE round ${ROUND} can start. Work from the repository root. Run each command and report. Do not edit, create, or delete anything.`,
    `1. git status --porcelain -- ${PROTECTED.join(' ')}`,
    `   The output must be empty.`,
    `2. git log -1 --format=%h -- ${PREDICTIONS}`,
    `   The output must be a commit hash.`,
    `3. find ${RUN_DIR} -name output.json 2>/dev/null | head -5`,
    `   The output must be empty, so this run cannot mix with an older one.`,
    `4. python ${RUNNER} --help and then python ${GRADER} --help`,
    `   Both must exit 0.`,
    `Set clean to true only if all four checks pass. Put one line per failed check in problems.`
  ].join('\n')
}

function trialPrompt(c, t) {
  const out = `${RUN_DIR}/${c.config}/${c.ticket}-t${t}`
  return [
    `You are the harness for one SPE trial in round ${ROUND}. You run commands and copy what they print. You do not judge, fix, retry, or edit anything.`,
    `Work from the repository root. Run these steps in order.`,
    `1. Run: python ${RUNNER} --round ${ROUND} --config ${c.config} --ticket ${c.ticket} --trial ${t} --out ${out}`,
    `   It writes ${out}/output.json and ${out}/transcript.jsonl. Put ${out}/output.json in output_path.`,
    `   If it exits non-zero, set ran to false, put the last 20 lines of stderr in run_error, and stop.`,
    `2. Run: python ${GRADER} --run ${out}/output.json --answers ${ANSWERS} --json`,
    `   Copy label.category and label.priority from output.json into category and priority.`,
    `   Copy category_ok and priority_ok from the grader JSON. If the grader fails, put its error in grader_error and set both to false.`,
    `3. Run: grep -n -E '${PEEK_PATTERN}' ${out}/transcript.jsonl`,
    `   Put each matching line, cut to 200 characters, in peek_hits. No match means an empty list.`,
    `4. Copy the customer reply text from output.json into reply_text exactly.`,
    `Set every string field you did not fill to an empty string. Do not open any file the steps above do not name.`
  ].join('\n')
}

function judgePrompt(r) {
  return [
    `You grade the tone of one customer support reply. Read the rubric in ${RUBRIC} and the ticket in ${TICKET_DIR}/${r.ticket}.json. Do not open any other file.`,
    `Grade tone only, as the rubric defines it. Category and priority are graded elsewhere, so ignore them.`,
    `The reply to grade:`,
    '<reply>',
    r.reply_text,
    '</reply>',
    `Return tone_pass, a score from 1 to 5, and one sentence of reason that quotes the reply.`
  ].join('\n')
}

// ---------- stages ----------
async function runTrial(c, t, ph) {
  const id = `${c.config}/${c.ticket}/t${t}`
  const rec = { config: c.config, ticket: c.ticket, trial: t, id, extra: t > BASE_TRIALS, status: 'skipped' }
  if (!reserve(TRIAL_USD, `trial ${id}`)) return rec
  let r
  try {
    r = await agent(trialPrompt(c, t), { label: `${id} run`, phase: ph, schema: TRIAL_SCHEMA, model: 'opus' })
  } catch (e) {
    rec.status = 'error'
    rec.error = String(e)
    return rec
  }
  Object.assign(rec, r)
  if (!r.ran) {
    rec.status = 'error'
    rec.error = r.run_error
    return rec
  }
  // Peek scan comes before grading counts. A trial that touched a protected path is void.
  if (r.peek_hits.length > 0) {
    rec.status = 'void'
    log(`VOID ${id}: transcript touched protected paths ${r.peek_hits.length} time(s)`)
    if (r.peek_hits.some(h => h.includes('answers.json'))) halt(`answer key reached by the system under test in ${id}`)
    return rec
  }
  if (r.grader_error) {
    rec.status = 'grader_error'
    graderErrors += 1
    log(`GRADER ERROR ${id}: ${r.grader_error.slice(0, 200)}`)
    if (graderErrors >= GRADER_ERROR_HALT) halt(`grader failed ${graderErrors} times`)
    return rec
  }
  rec.status = 'graded'
  rec.both_ok = r.category_ok && r.priority_ok
  return rec
}

async function judgeTrial(rec, ph) {
  if (rec.status === 'graded') {
    if (!rec.reply_text.trim()) {
      // Code check first. An empty reply fails tone without a paid judge call.
      rec.tone_status = 'code'
      rec.tone_pass = false
      rec.tone_reason = 'empty reply'
    } else if (reserve(JUDGE_USD, `judge ${rec.id}`)) {
      try {
        const j = await agent(judgePrompt(rec), { label: `${rec.id} judge`, phase: ph, schema: JUDGE_SCHEMA, model: 'opus' })
        rec.tone_status = 'judged'
        rec.tone_pass = j.tone_pass
        rec.tone_score = j.score
        rec.tone_reason = j.reason
      } catch (e) {
        rec.tone_status = 'error'
        rec.tone_reason = String(e)
      }
    } else {
      rec.tone_status = 'skipped'
    }
  }
  done += 1
  if (done % 50 === 0) log(`${done} trials finished. Estimated spend $${spent.toFixed(2)} of $${CAP_USD}.`)
  return rec
}

function runItems(items, ph) {
  return pipeline(items, it => runTrial(it.c, it.t, ph), rec => judgeTrial(rec, ph))
}

// ---------- scoring ----------
function isSplit(recs) {
  const g = recs.filter(r => r.status === 'graded')
  const both = new Set(g.map(r => r.both_ok))
  const tone = new Set(g.filter(r => typeof r.tone_pass === 'boolean').map(r => r.tone_pass))
  return both.size > 1 || tone.size > 1
}

function score(recs, plannedPerConfig) {
  const out = {}
  for (const config of CONFIGS) {
    const rs = recs.filter(r => r.config === config)
    const g = rs.filter(r => r.status === 'graded')
    const toned = g.filter(r => typeof r.tone_pass === 'boolean')
    const cells = Array.from(groupByCell(g).values())
    out[config] = {
      planned: plannedPerConfig[config] ?? 0,
      statuses: countBy(rs, r => r.status),
      category_acc: rate(g, r => r.category_ok),
      priority_acc: rate(g, r => r.priority_ok),
      both_acc: rate(g, r => r.both_ok),
      tone_pass_rate: rate(toned, r => r.tone_pass),
      tone_unscored: g.length - toned.length,
      tickets_scored: cells.length,
      tickets_all_trials_ok: cells.filter(cs => cs.every(r => r.both_ok)).length,
      split_cells: cells.filter(cs => isSplit(cs)).length
    }
  }
  return out
}

// ---------- run ----------
phase('Preflight')
const baseItems = CELLS.flatMap(c => Array.from({ length: BASE_TRIALS }, (_, i) => ({ c, t: i + 1 })))
const projected = ANALYSIS_USD + baseItems.length * (TRIAL_USD + JUDGE_USD) + RESERVE_USD
log(`Round ${ROUND}${DRY ? ' DRY RUN' : ''}: ${CELLS.length} cells x ${BASE_TRIALS} trials = ${baseItems.length} trials. Projected base spend $${projected.toFixed(2)} against a cap of $${CAP_USD}.`)
if (projected > CAP_USD) log(`WARNING: projected spend crosses the cap. Trials past the cap will be skipped and logged.`)

reserve(ANALYSIS_USD, 'preflight')
const pre = await agent(preflightPrompt(), { label: 'preflight', phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: 'opus' })
if (!pre.clean) {
  log(`HALT: preflight failed. ${pre.problems.join(' | ')}`)
  return { round: ROUND, dry_run: DRY, halted: 'preflight', problems: pre.problems, est_spent_usd: +spent.toFixed(2) }
}

phase('Trials')
const baseRecs = await runItems(baseItems, 'Trials')

phase('Extra trials')
const splitKeys = Array.from(groupByCell(baseRecs).entries())
  .filter(([, rs]) => isSplit(rs))
  .map(([k]) => k)
  .sort()
const perCell = EXTRA_PER_SPLIT
const fundedCells = perCell > 0 ? splitKeys.slice(0, Math.floor(EXTRA_MAX / perCell)) : []
const unfundedCells = splitKeys.slice(fundedCells.length)
if (unfundedCells.length) log(`Extra-trial cap reached. ${unfundedCells.length} split cells get no extra trials: ${unfundedCells.join(', ')}`)
const extraItems = fundedCells.flatMap(k => {
  const [config, ticket] = k.split('/')
  return Array.from({ length: perCell }, (_, i) => ({ c: { config, ticket }, t: BASE_TRIALS + i + 1 }))
})
log(`${splitKeys.length} split cells. Running ${extraItems.length} extra trials.`)
const extraRecs = extraItems.length ? await runItems(extraItems, 'Extra trials') : []
const all = baseRecs.concat(extraRecs)

phase('Score')
const plannedBase = countBy(baseItems, it => it.c.config)
const plannedAll = countBy(baseItems.concat(extraItems), it => it.c.config)
const scoresBase = score(baseRecs, plannedBase)
const scoresWithExtras = score(all, plannedAll)
const statusCounts = countBy(all, r => r.status)
const accountedFor = Object.values(statusCounts).reduce((a, b) => a + b, 0)
const accounting = {
  planned_trials: baseItems.length + extraItems.length,
  accounted_for: accountedFor,
  accounting_ok: accountedFor === baseItems.length + extraItems.length,
  ran_count: all.filter(r => r.ran === true).length,
  statuses: statusCounts,
  tone_statuses: countBy(all.filter(r => r.status === 'graded'), r => r.tone_status),
  voids: all.filter(r => r.status === 'void').map(r => ({ id: r.id, peek_hits: r.peek_hits })),
  skips_logged: skips.length
}
log(`Base scores: ${JSON.stringify(scoresBase)}`)
log(`Accounting: ${JSON.stringify({ ...accounting, voids: accounting.voids.length })}`)

let failureAnalysis = null
let critic = null

if (!DRY) {
  phase('Failure analysis')
  const failing = all
    .filter(r => r.status !== 'graded' || !r.both_ok || r.tone_pass === false)
    .map(r => ({
      id: r.id, status: r.status, category: r.category ?? '', priority: r.priority ?? '',
      category_ok: r.category_ok ?? null, priority_ok: r.priority_ok ?? null,
      tone_pass: r.tone_pass ?? null, tone_reason: r.tone_reason ?? '', error: r.error ?? r.grader_error ?? ''
    }))
  if (reserve(ANALYSIS_USD, 'failure analysis', { analysis: true })) {
    failureAnalysis = await agent([
      `You analyze the failures from SPE round ${ROUND}. The trials are finished, so you may read anything under ${RUN_DIR}, ${ANSWERS}, ${GRADER}, ${RUBRIC}, and spe/failures.md. Do not edit any file.`,
      `Each id is config/ticket/trial. Outputs are at ${RUN_DIR}/<config>/<ticket>-t<trial>/output.json with transcript.jsonl beside them.`,
      `Group the failures into types. Reuse an existing F-number from spe/failures.md when a type matches, and put it in matches_existing. Otherwise leave matches_existing empty.`,
      `Give each type a name, kind, what happened, how to spot it, the ids it was seen in, a count, and a fix.`,
      `Look for grader bugs on purpose. If grade.py or the judge looks wrong for a trial, list it in grader_suspects with the reason. A grader bug is a failure type of kind grader.`,
      `Base scores by config: ${JSON.stringify(scoresBase)}`,
      `Failing, void, and errored trials: ${JSON.stringify(failing)}`
    ].join('\n'), { label: 'failure analysis', phase: 'Failure analysis', schema: FAILURE_SCHEMA, model: 'opus' })
  }

  phase('Completeness critic')
  if (reserve(ANALYSIS_USD, 'completeness critic', { analysis: true })) {
    critic = await agent([
      `You are the completeness critic for SPE round ${ROUND}. Work from the repository root. Do not edit anything.`,
      `1. Run: git status --porcelain -- ${PROTECTED.join(' ')}`,
      `   Set integrity_clean to true only if the output is empty. A change means the grader, answer key, plan, or prediction moved during the run.`,
      `2. Run: find ${RUN_DIR} -name output.json | wc -l`,
      `   Put the number in output_files_found. It must equal ran_count in the accounting below.`,
      `3. Check the accounting. Every planned trial must be graded, void, error, grader_error, or skipped. Every graded trial needs a tone result or a logged reason. Every void needs peek hits.`,
      `4. Check that the base scores use base trials only, so they are comparable with ${PREDICTIONS}.`,
      `5. Check the failure analysis covers every failing id or says why not.`,
      `List each gap in gaps. List in halt_reasons any leaked answer key, broken grader, budget cap hit, or decision only the user can make. Set complete to true only if gaps is empty.`,
      `Accounting: ${JSON.stringify(accounting)}`,
      `Halted: ${halted ?? 'no'}. Estimated spend $${spent.toFixed(2)} of $${CAP_USD}.`,
      `Skips: ${JSON.stringify(skips)}`,
      `Base scores: ${JSON.stringify(scoresBase)}`,
      `Scores with extra trials: ${JSON.stringify(scoresWithExtras)}`,
      `Failure analysis: ${JSON.stringify(failureAnalysis)}`
    ].join('\n'), { label: 'completeness critic', phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: 'opus' })
  }
}

log(`Done. Halted: ${halted ?? 'no'}. Estimated spend $${spent.toFixed(2)} of $${CAP_USD}. ${skips.length} skips logged.`)

return {
  round: ROUND,
  dry_run: DRY,
  run_dir: RUN_DIR,
  halted,
  est_spent_usd: +spent.toFixed(2),
  cap_usd: CAP_USD,
  cost_estimates_usd: { trial: TRIAL_USD, judge: JUDGE_USD, analysis: ANALYSIS_USD },
  scores_base: scoresBase,
  scores_with_extras: scoresWithExtras,
  split_cells: splitKeys,
  split_cells_without_extras: unfundedCells,
  accounting,
  skips,
  failure_analysis: failureAnalysis,
  critic,
  trials: all.map(r => ({ ...r, reply_text: (r.reply_text ?? '').slice(0, 500) }))
}
```
